/* Nestlé India-only learning profile. Product groups are not separate profit segments. */
(()=>{
 const id='nestle-india',c=window.COMPANIES.find(c=>c.id===id),previous=window.companyPrimer;
 const root='https://www.nestle.in/';
 const urls={company:root+'about-us/at-a-glance',brands:root+'info/sitemap',annual:root+'sites/g/files/pydnoa451/files/2026-06/AnnualReport2025-26andAGMNotice.pdf',figures:root+'investors/keyfigures',foods:root+'brands/foods',coffee:root+'brands/coffee',milk:root+'brands/dairy',nutrition:root+'brands/nutrition',chocolate:root+'brands/chocolatesandconfectionery',professional:root+'media/pressreleases/allpressreleases/nestl%C3%A9-professional-reaches-landmark-1000th-retail-one-kiosk-india',nespresso:root+'sites/g/files/pydnoa451/files/2025-03/NSEBSESTXintimationNespressosigned.pdf',royalty:root+'investors/stockandfinancials/royalty'};
 const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const note=(url,label,location='')=>`<p class="source-note"><a href="${url}" target="_blank" rel="noopener">${label} ↗</a>${location?` · ${location}`:''}</p>`;
 c.summary='The Indian food and beverage business behind MAGGI, NESCAFÉ, KITKAT and MILKMAID, with nutrition, pet care and out-of-home offerings too.';
 c.description='Nestlé India develops, manufactures and sells food and beverages. Its products serve different occasions: preparing a meal, making coffee, buying a snack or using dairy and nutrition products. Those occasions have different ingredients, pack formats, customers and costs.';
 c.money='Nestlé India earns revenue by supplying food and beverage products through shops, retail chains, online channels and out-of-home partners. Ingredients, packaging, manufacturing, quality control, delivery, advertising and licence arrangements affect the earnings left from sales. Selling more, changing prices and selling a different balance of products can have different effects.';
 window.COMPANY_OVERVIEWS[id]={customers:'Households buy through retailers and online channels. Nestlé Professional also serves food-service and out-of-home customers. The distributor or retailer buying from the company can be different from the person who eats or drinks the product.',drivers:'Quantities, selling prices, product mix and ingredient costs, especially across milk, coffee, cocoa and other inputs. Distribution, food quality and the cost of building capacity also matter.'};
 const extras=[['CERELAC','Milk products and nutrition · reported brand'],['NAN','Milk products and nutrition · reported brand'],['NESPRESSO','Coffee and machines · India distribution arrangement'],['Purina PetCare','Pet food · within Prepared Dishes and Cooking Aids'],['Nestlé Professional','Out-of-home food and beverage offerings · sales channel']];
 c.products.push(...extras.filter(([name])=>!c.products.some(([old])=>name===old)));
 c.productNote='Selected Indian brand and offering families from the official product directory and FY 2025–26 report. Variants and pack sizes are grouped. Nestlé Professional is a sales channel, and a brand or product group is not a separately disclosed profit segment. Availability differs by product and channel.';
 c.watch=[
 ['Is demand increasing, or are prices and pack sizes changing?','Are more goods being bought, or is sales growth coming from pricing and a different product mix?'],
 ['Which ingredient costs are affecting which products?','Do changes in milk, coffee, cocoa and other costs flow through to pricing and the earnings left after costs?'],
 ['Is distribution creating repeat purchases?','Are new outlets, rural reach, online channels and out-of-home partners bringing sustained demand?'],
 ['Are quality and compliance protecting trust?','What do official disclosures say about food safety, labels, product standards and any corrective action?'],
 ['Is new capacity turning into useful production and cash?','Do factory spending and new product investments become sales that cover their ongoing costs?'],
 ['Are the profit definition, period and India reporting scope clear?','Are you reading Nestlé India’s company figures, product-group sales or the worldwide Nestlé group’s results?']
 ];
 window.COMPANY_RESEARCH_GUIDES[id]=[
 'Read the company’s volume and category commentary alongside sales. Volume describes quantity on the stated basis; mix describes which products and formats make up sales. Smaller packs, price changes and premium products can change the picture. Compare quantities or equivalent measures where disclosed rather than treating every pack as the same size.',
 'Follow the ingredient-cost explanation in the results and annual report. Milk, coffee and cocoa do not necessarily rise or fall together, and stock purchased earlier can delay the effect on costs. Check selling-price changes, promotional spending and the stated margin definition together. A higher-priced product is not automatically more profitable.',
 'Read commentary on established outlets, newer geographies, e-commerce and Nestlé Professional. Separate supplying stock into a distribution channel from shoppers actually buying it. More outlets or branded kiosks are evidence of reach, not a published repeat-purchase rate or proof that Nestlé India owns each outlet.',
 'Use the company’s official statements, regulatory disclosures and annual-report risk discussion. Identify the product, facility, date and scope of any issue; distinguish an allegation from a regulator’s finding and the company’s response. Read compliance and product-quality evidence without treating a brand name as proof of a nutritional or health benefit.',
 'Compare investment spending with commissioning, production and demand commentary. Commissioning means bringing an asset into use; utilisation describes how much of its capacity is used. Read depreciation, inventory and operating cash flow as well as profit. A factory announcement or extra capacity is not yet a sale or a return on the investment.',
 'Start with the period and standalone/consolidated labels. Nestlé India reports one Food operating segment, while disclosing sales by product group. The category sales do not establish category profit. Check exceptional items, related-party and licence fees, and reporting-period length before comparing years. Global Nestlé product margins must not be substituted for India figures.'
 ];
 c.risks=[
 ['Ingredient inflation meets price-sensitive shoppers','More expensive milk, coffee, cocoa, grains or packaging can raise costs. Increasing prices or reducing pack sizes may protect the amount left per sale but can also change demand and customer choice.'],
 ['Food safety or labelling problems disrupt trust','Food businesses depend on consistent quality and compliance. A product issue, restriction or recall can interrupt supply and add costs. Assess the actual scope in official disclosures rather than assuming it affects every product.'],
 ['Consumers choose alternatives','Other packaged brands, regional products, fresh food and changing preferences compete for household spending. Advertising and new launches can support demand but also cost money.'],
 ['Expansion absorbs money before it earns enough','Factories, equipment and new distribution require spending. If demand takes longer to arrive, operating costs and depreciation can weigh on results while stock and customer payments tie up cash.'],
 ['A headline comparison hides a different measure','Product sales, revenue from operations, operating profit and profit after tax measure different things. Changes in product mix, exceptional items, group arrangements or period length can make a simple growth comparison misleading.']
 ];
 c.update=['Read what is inside a category name','In Nestlé India’s report, Prepared Dishes and Cooking Aids includes cereals and pet food as well as products such as noodles and sauces. Growth in that group need not mean the same change in MAGGI sales. Read its contents and the category commentary before attributing a group’s performance to one familiar brand.'];
 c.question='If one Nestlé India product group has the most sales, must it also make the most profit?';
 c.answer='No. Ingredients, production, advertising, distribution and other costs differ. The cited India disclosures show product-group sales and company-level profit, not a separate profit for each group or brand. Ranking sales is not a way to calculate an undisclosed profit split.';
 const additions=[['Indian product and offering directory',urls.brands],['Dairy portfolio',urls.milk],['Nutrition portfolio',urls.nutrition],['Foods portfolio',urls.foods],['FY 2025–26 annual report · product groups and accounts',urls.annual],['Official key financial figures and period notes',urls.figures],['Nestlé Professional · out-of-home business',urls.professional],['NESPRESSO India distribution announcement',urls.nespresso]];
 c.sources.push(...additions.filter(([,url])=>!c.sources.some(([,old])=>url===old)));
 const basics=`<section class="content-section company-primer" id="nestle-basics"><div class="number">START WITH THE PRODUCTS</div><h2>Different things to eat and drink. One Indian food business.</h2><p>Think of a MAGGI noodle pack, a jar of NESCAFÉ, a KITKAT bar or a tin of MILKMAID. They serve different occasions. Nestlé India brings together product development, sourcing, production, quality control, marketing and sales to put those goods within customers’ reach.</p><dl class="primer-definitions"><div><dt>Company → Nestlé India</dt><dd>The Indian business whose operations and accounts this page explains. The global Nestlé group has a wider portfolio and a different set of financial results.</dd></div><div><dt>Brand → MAGGI</dt><dd>A name covering products such as noodles, sauces and cooking aids. Different packs and recipes can sit under the same name.</dd></div><div><dt>Product group → a family of offerings</dt><dd>The annual report groups similar products to disclose sales. A product group helps you see what sells; it does not automatically come with a separate profit number.</dd></div><div><dt>Operating segment → Food</dt><dd>Nestlé India reports one Food operating segment. The product groups below sit within that business rather than being separately reported profit divisions.</dd></div></dl>${note(urls.annual,'Nestlé India annual report','Notes 24 and 42 · product sales and segment reporting')}
 <h3>Connect the familiar names to the product groups</h3><div class="primer-groups">${[
 ['Milk Products and Nutrition','Dairy whitener, condensed milk, milk products and nutrition products.','EVERYDAY, MILKMAID, Nestlé a+, CERELAC and NAN are examples from the Indian directory or report.','Milk sourcing, processing, quality requirements and the mix of products affect costs and demand.',urls.milk],
 ['Prepared Dishes and Cooking Aids','Noodles, sauces, seasonings, pasta, cereals and pet food in the reporting group.','MAGGI noodles and cooking aids; Purina PetCare is also included in this group in the annual report.','Convenience, taste, pack size, grain and ingredient costs, and distribution all matter.',urls.foods],
 ['Powdered and Liquid Beverages','Coffee, instant tea and ready-to-drink beverages in the reporting group.','NESCAFÉ ranges illustrate the different coffee formats; NESTEA is another beverage offering.','Coffee input costs and the balance of basic packs, specialised products and ready-to-drink formats can change both sales and costs.',root+'brands/coffee'],
 ['Confectionery','Chocolate, wafer-based snacks and sugar confectionery.','KITKAT, MUNCH, MILKYBAR, BAR-ONE and POLO are recognisable examples.','Cocoa, milk, sugar and packaging costs, pack sizes and small, unplanned purchases influence the business.',urls.brands]
 ].map(([name,offering,examples,drivers,url])=>`<div><h3>${name}</h3><p><strong>What it includes:</strong> ${offering}</p><p>${examples}</p><p>${drivers}</p>${note(url,'Official product reference')}</div>`).join('')}</div><p class="source-note">The annual report defines the reporting groups; the product pages identify examples. Product placement in a website menu can differ from financial reporting.</p>
 <h3>Who buys, and who uses the product?</h3><p>A household might buy a pack from a local shop or online retailer. The company’s immediate customer may be a distributor or retail business supplying that shopper. Through <strong>Nestlé Professional</strong>, it also serves food-service and out-of-home occasions with partners.</p><p>These are different routes to the customer, not necessarily new product groups. Selling through a shop, a website or a branded kiosk does not establish that Nestlé India owns that outlet.</p>${note(urls.professional,'Nestlé Professional: the Indian out-of-home business')}</section>`;
 const specifics=`<section class="content-section company-primer" id="nestle-specifics"><div class="number">HOW THIS BUSINESS WORKS</div><h2>From ingredients to another purchase.</h2><ol class="primer-route"><li><strong>Source ingredients and products</strong><span>Arrange milk, coffee, cocoa, grains and other inputs, packaging or finished goods, depending on the offering.</span></li><li><strong>Produce, check and package</strong><span>Turn ingredients into products, control quality and prepare them for storage and distribution. Requirements differ across products.</span></li><li><strong>Reach a shopping or food-service channel</strong><span>Move goods through the relevant distributor, retailer, online or out-of-home arrangement.</span></li><li><strong>Earn the next purchase</strong><span>The user consumes the product and may choose it again. Availability, taste, price, trust and alternatives all affect that choice.</span></li></ol><p>This is a simplified route for understanding the business. A locally manufactured pack, an imported offering and a partner-operated outlet can have different supply arrangements.</p>${note(urls.company,'Nestlé India: products and supply relationships')}
 <h3>How does a sale become earnings?</h3><p>Sales have to cover ingredients, packaging, production, people, transport, quality control, advertising and other expenses. A consumer’s shop price is not automatically the amount Nestlé India records as revenue. The channel, taxes and discounts affect the route from a purchase to company sales.</p><p>Quantity, price and mix also differ. More coffee sold is different from the same quantity sold at a higher price. A shift to a more expensive coffee format changes the product mix, but extra costs may accompany it.</p>
 <div class="primer-examples"><div><h4>Compare pack sizes as well as prices</h4><p>A lower amount paid for a pack can reflect a smaller quantity inside it.</p><span>To understand affordability and demand, look at quantity or equivalent measures rather than counting every pack as identical.</span></div><div><h4>Follow milk, coffee and cocoa separately</h4><p>These inputs have different supply and price cycles. A change affecting chocolate need not have the same effect on a noodle pack.</p><span>Read which costs changed, when they enter production and what the company says about pricing and demand.</span></div><div><h4>Separate sales growth from cash available</h4><p>Stock, customer amounts still due and new manufacturing investment can use money while sales and reported profit increase.</p><span>Operating cash flow and investment spending help explain what happened to the money.</span></div></div>
 <h3>Growth can mean more reach or a different offering</h3><p>New outlets, smaller towns, online shopping and out-of-home occasions can help products reach different customers. <strong>Penetration</strong> means reaching more buyers in a market. It is different from the same buyers purchasing more often.</p><p><strong>Premiumisation</strong> means customers choosing higher-priced or more specialised offerings. NESPRESSO adds a coffee-and-machines offering with a stated India distribution partnership. Its channel and cost structure need to be understood rather than treating every coffee sale as the same.</p>${note(urls.nespresso,'NESPRESSO India: offering and distribution arrangement')}
 <details class="primer-detail"><summary>Useful words in Nestlé India’s results</summary><dl class="primer-glossary">${[
 ['Volume and product mix','Volume describes quantities on the company’s stated basis. Mix describes the balance of products and formats sold. Both can change alongside prices.'],
 ['Commodity costs','Costs of traded ingredients or raw materials, such as coffee, cocoa or milk inputs. Supply, weather, demand and stock bought earlier can influence their effect on costs.'],
 ['Margin','A specified profit measure divided by the corresponding sales. Identify the costs included before comparing margins across companies or periods.'],
 ['Exceptional items','Separately identified charges or credits that affect reported profit. Read the explanation before treating them as part of the normal operating trend.'],
 ['Capacity and utilisation','Capacity is how much a facility can produce; utilisation is how much of that ability is being used. A new plant needs demand and efficient operation to earn returns.'],
 ['Royalties and related-party arrangements','Royalties are payments for agreed rights such as brands or know-how. Related-party transactions include dealings with group entities. Read the company’s licence and transaction disclosures as part of understanding its costs.'],
 ['Product sales and revenue from operations','Product sales describe goods sold. Revenue from operations can also include other operating revenue. A product-sales mix should be calculated using the matching product-sales total.']
 ].map(([term,meaning])=>`<div><dt>${term}</dt><dd>${meaning}</dd></div>`).join('')}</dl></details>${note(urls.annual,'Annual report: business review, costs and related-party notes')}<p class="source-note">Business explanations checked 29 October 2026 using the linked Indian disclosures. They describe how to investigate the business; they are not findings that every new product, outlet or factory earns an attractive return.</p></section>`;
 function numbers(){const f=window.COMPANY_FINANCIALS[id],p=f.productSales,fmt=n=>new Intl.NumberFormat('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n);return `<div class="primer-number-guide"><h3>Which product groups bring in sales?</h3><p>This is <strong>sales only</strong> for FY 2025–26, on the standalone India basis. Category and brand profits are not supplied by this table.</p><table class="financial-table"><caption class="sr-only">Nestlé India standalone product-group sales, FY 2025–26. No category profit allocation.</caption><thead><tr><th scope="col">Product group</th><th scope="col">Sales<br><small>₹ crore</small></th><th scope="col">Share of product sales<br><small>% · calculated</small></th></tr></thead><tbody>${p.rows.map(r=>`<tr><th scope="row">${esc(r.name)}</th><td>${fmt(r.revenue)}</td><td>${(r.revenue/p.total*100).toFixed(2)}%</td></tr>`).join('')}</tbody><tfoot><tr><th scope="row">Sale of products</th><td>${fmt(p.total)}</td><td>100%</td></tr></tfoot></table><p>Milk Products and Nutrition has the most reported product sales in this table. That does not establish which group earns the most profit, because separate group profits are not disclosed in the cited segment note.</p><p>Product sales of ₹${fmt(p.total)} crore plus other operating revenue of ₹${fmt(p.otherOperatingRevenue)} crore give the company’s revenue from operations of ₹${fmt(f.rows[0].revenue)} crore above. Sales shares are calculated as group sales ÷ total product sales × 100 and rounded for display. Independently rounded percentages may not add to exactly 100%. They are not shares of profit.</p>${note(p.source,'Official annual report: source of product sales and definitions',esc(p.location))}<h3>Read the company profit without assigning it to a brand</h3><p>The overall ₹${fmt(f.rows[0].profit)} crore profit after tax is a company result. It includes the reported expenses, exceptional items and tax. Dividing it among MAGGI, NESCAFÉ, KITKAT or these product groups in proportion to their sales would invent a profit breakdown.</p><details class="primer-detail"><summary>Why historical comparisons need a period check</summary><p>FY 2025–26 covers 12 months ended 31 March 2026. Nestlé India’s transition year 2023–24 covered 15 months, so its raw sales or profit totals should not be compared with a 12-month year as if the periods were equal. The company explains this in its key-figures footnote.</p>${note(urls.figures,'Official period-comparability note')}</details><p>Next, read operating cash flow, inventory, customer and supplier balances, factory investment and the related-party notes. Those checks connect the earnings total to the cash needed to run and expand the business.</p></div>`}
 if(window.PRODUCT_VISUALS){const old=window.PRODUCT_VISUALS[id],first=[old.find(p=>p.name==='MAGGI Noodles'),old.find(p=>p.name==='NESCAFÉ Classic')].filter(Boolean);const drawings=[['Milk & nutrition','Dairy and nutrition product group','milk-nutrition',urls.milk],['Confectionery','Chocolate, wafers and sugar confectionery','confectionery',urls.brands],['Purina PetCare','Pet food · included in Prepared Dishes and Cooking Aids','petcare',urls.annual],['Nestlé Professional','Out-of-home offerings · customer channel','professional',urls.professional]].map(([name,category,slug,url])=>({name,category,url,image:`assets/products/nestle-business-${slug}.svg`,kind:'illustration',alt:`${name} — conceptual illustration, not a product photograph`}));window.PRODUCT_VISUALS[id]=[...first,...drawings,...old.filter(p=>!first.includes(p))];}
 window.companyPrimer={skipBusiness(company){return company.id===id||!!previous?.skipBusiness(company);},render(company,slot){if(company.id!==id)return previous?.render(company,slot)||'';return slot==='basics'?basics:slot==='specifics'?specifics:slot==='numbers'?numbers():'';},contents(company){return company.id===id?[['nestle-basics','Nestlé India from the basics'],['nestle-specifics','How Nestlé India works']]:previous?.contents(company)||[]}};
})();
